38	//! Enumerate LoRA weight tensor names from an engine's I/O bindings.
39	std::vector<std::string> collectLoraWeightsTensorNames(nvinfer1::ICudaEngine const& engine)
40	{
41	    std::vector<std::string> loraTensorNames;
42	    int32_t const numIO = engine.getNbIOTensors();
43	    for (int32_t i = 0; i < numIO; ++i)
44	    {
45	        std::string const name(engine.getIOTensorName(i));
