56	void LoRAManager::loadWeights(std::string const& name, std::filesystem::path const& path, cudaStream_t stream)
57	{
58	    LOG_INFO("LoRAManager: loading adapter '%s' from %s", name.c_str(), path.string().c_str());
59	
60	    std::vector<rt::Tensor> tensors;
61	    bool const ok = safetensors::loadSafetensors(path, tensors, stream);
62	    ELLM_CHECK(ok, "LoRAManager: failed to load safetensors from " + path.string());
63	
64	    WeightMap weights;
65	    for (auto& t : tensors)
66	    {
67	        std::string bindingName = t.getName();
68	        weights.emplace(std::move(bindingName), std::move(t));
69	    }
70	
71	    LOG_INFO("LoRAManager: adapter '%s' loaded with %zu binding(s)", name.c_str(), weights.size());
72	
