96	rt::Tensor& LoRAManager::getActiveWeight(std::string const& bindingName)
97	{
98	    if (mActiveAdapterName.empty())
99	    {
100	        // Lazy-initialize dummy tensor on first use. Zero-fill so any TRT
101	        // engine that reads it (rank=1 LoRA contraction on inactive adapters)
102	        // sees deterministic zeros rather than uninitialized GPU memory.
103	        if (mDummyTensor.isEmpty())
104	        {
105	            mDummyTensor = rt::Tensor({1}, DeviceType::kGPU, nvinfer1::DataType::kHALF, "LoRAManager::dummy");
106	            CUDA_CHECK(cudaMemset(mDummyTensor.rawPointer(), 0, mDummyTensor.getMemoryCapacity()));
107	        }
108	        return mDummyTensor;
109	    }
110	
111	    auto const adapterIt = mAdapters.find(mActiveAdapterName);
112	    ELLM_CHECK(adapterIt != mAdapters.end(),
113	        "LoRAManager: active adapter '" + mActiveAdapterName + "' disappeared unexpectedly");
114	
115	    auto const weightIt = adapterIt->second.find(bindingName);
116	    ELLM_CHECK(weightIt != adapterIt->second.end(),
117	        "LoRAManager: binding '" + bindingName + "' not found in adapter '" + mActiveAdapterName + "'");
118	
119	    return weightIt->second;
120	}
