156	bool LoRAManager::hasWeightFor(std::string const& bindingName) const noexcept
157	{
158	    if (mActiveAdapterName.empty())
159	    {
160	        return false;
161	    }
162	    auto const adapterIt = mAdapters.find(mActiveAdapterName);
163	    if (adapterIt == mAdapters.end())
164	    {
165	        return false;
166	    }
167	    return adapterIt->second.find(bindingName) != adapterIt->second.end();
