170	void LoRAManager::initializeEngineBindings(EngineExecutor const& runner)
171	{
172	    constexpr int32_t kEmptyLoraRank = 1;
173	
174	    std::vector<std::string> names = collectLoraWeightsTensorNames(runner.getEngine());
175	    std::map<std::string, rt::Tensor> dummyTensors;
176	
177	    for (auto const& name : names)
178	    {
179	        nvinfer1::Dims const maxShape
180	            = runner.getProfileShape(name.c_str(), /*profileIndex=*/0, nvinfer1::OptProfileSelector::kMAX);
181	        nvinfer1::Dims dummyShape = maxShape;
182	        if (name.find(binding_names::kLoraAPrefix) != std::string::npos)
183	        {
184	            // LoRA A: [k, rank] → set rank (last dim) to 1
185	            dummyShape.d[dummyShape.nbDims - 1] = kEmptyLoraRank;
186	        }
187	        else if (name.find(binding_names::kLoraBPrefix) != std::string::npos)
188	        {
189	            // LoRA B: [rank, n] → set rank (first dim) to 1
190	            dummyShape.d[0] = kEmptyLoraRank;
191	        }
192	        std::vector<int64_t> shape(dummyShape.nbDims);
193	        for (int32_t d = 0; d < dummyShape.nbDims; ++d)
194	        {
195	            shape[d] = dummyShape.d[d];
196	        }
197	        // Zero-fill: when no adapter is active these dummies are bound directly
198	        // to the engine's lora_A_*/lora_B_* inputs, so the rank-1 contraction
199	        // must read deterministic zeros, not uninitialized cudaMalloc memory.
200	        auto [it, inserted] = dummyTensors.emplace(
201	            name, rt::Tensor(shape, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "loraDummy_" + name));
202	        CUDA_CHECK(cudaMemset(it->second.rawPointer(), 0, it->second.getMemoryCapacity()));
203	    }
204	
205	    mEngineBindingNames = std::move(names);
206	    mEngineDummyTensors = std::move(dummyTensors);
207	    LOG_INFO("LoRAManager: registered %zu engine LoRA binding name(s)", mEngineBindingNames.size());
208	}
209	
210	void LoRAManager::refreshTensorMap(TensorMap& map)
211	{
212	    for (auto const& engineBindingName : mEngineBindingNames)
213	    {
214	        // Exact name match works for non-fused projections. Fused engines use
215	        // a different naming convention (e.g. `qkv_proj.*` vs the adapter's
216	        // separate `q_proj.*` / `k_proj.*` / `v_proj.*`); for those bindings
217	        // we fall back to the per-binding dummy tensor.
218	        if (hasWeightFor(engineBindingName))
219	        {
220	            map.set(engineBindingName, getActiveWeight(engineBindingName));
221	            continue;
222	        }
223	
224	        auto it = mEngineDummyTensors.find(engineBindingName);
225	        if (it != mEngineDummyTensors.end())
226	        {
227	            map.set(engineBindingName, it->second);
228	        }
229	    }
230	}
